<?php require_once __DIR__.'/_header.php';$rows=db()->query("SELECT v.title,v.views,COALESCE(SUM(vv.watch_seconds),0) watch_seconds,COUNT(vv.id) events FROM videos v LEFT JOIN video_views vv ON vv.video_id=v.id GROUP BY v.id ORDER BY v.views DESC LIMIT 100")->fetchAll();?><h1>Analytics</h1><table><tr><th>Video</th><th>Views</th><th>View Events</th><th>Watch Seconds</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=number_format($r['views'])?></td><td><?=number_format($r['events'])?></td><td><?=number_format($r['watch_seconds'])?></td></tr><?php endforeach;?></table><?php require __DIR__.'/_footer.php';